/** Build the four stable documentation sections for one node type. */
const nodeDoc = (behavior, input, output, limitations) => ({ behavior, input, output, limitations })
const workflowNodeDocDetails = {
  START: nodeDoc('Accepts caller input and establishes the workflow execution context.', 'Structured parameters submitted by a manual, API, webhook, schedule, or message trigger.', 'Returns workflow input unchanged for downstream input references.', 'Performs no external action and needs no configuration; a top-level graph has one start entry.'),
  END: nodeDoc('Resolves the optional output expression and completes the workflow.', 'Upstream results and the complete workflow context.', 'Returns configured output, or all node outputs when output is omitted.', 'Cannot have a following edge; the result remains subject to workflow payload limits.'),
  LLM: nodeDoc('Sends system and user prompts through a route or a specific model.', 'Resolved prompts, model source, temperature, and reasoning settings.', 'Returns content, actual model, and input, output, and total token counts.', 'The model must support the selected type; providers may time out, rate-limit, or return unreliable content.'),
  HTTP: nodeDoc('Sends an HTTP request under the platform egress policy.', 'URL, method, headers, query parameters, body, and upstream expressions.', 'Returns httpStatus, durationMs, body, and json when the body parses as JSON.', 'SSRF, TLS, response-size, and timeout controls apply; remote side effects are not rolled back.'),
  AGENT: nodeDoc('Lets a model select controlled HTTP or sub-workflow tools within a step limit.', 'Task prompt, model configuration, and an explicit tool list.', 'Returns the final agent content and structured tool-call results.', 'Tool names must be unique; recursion, steps, egress, and sub-workflow ownership are restricted.'),
  RAG: nodeDoc('Retrieves knowledge chunks and asks a text model for a cited answer.', 'Query, an owned knowledge base, Top-K, score threshold, and text-model configuration.', 'Returns answer, knowledge-base data, model/token statistics, citations, and matches.', 'Top-K is 1–50, threshold is 0–1, context is capped at 20,000 characters, and retrieved text is untrusted.'),
  KNOWLEDGE_RETRIEVAL: nodeDoc('Runs vector retrieval without calling a generative model.', 'Query, an owned knowledge base, Top-K, and score threshold.', 'Returns knowledge-base identity, count, and matches with chunk sources and scores.', 'Query is capped at 500 characters, Top-K at 1–50, threshold at 0–1, and the owned knowledge base must be indexed.'),
  KNOWLEDGE_UPSERT: nodeDoc('Extracts, chunks, embeds, and indexes text or a Base64 document.', 'Owned knowledge base, input mode, content, filename, and content type.', 'Returns documentId, fileName, status, and chunkCount.', 'Indexing has non-rollback vector side effects; empty, invalid, oversized, or cross-owner input fails.'),
  CONDITION: nodeDoc('Evaluates one structured condition and selects the true or false branch.', 'Left value, operator, optional right value, and referenced context.', 'Returns matched and continues from the matching true/false port.', 'Only platform operators are supported; missing references or incompatible types may not match.'),
  ITERATION: nodeDoc('Sequentially runs a nested graph for each array element.', 'Array expression, maximum iterations, and a nested graph with start/end nodes.', 'Returns iterations and ordered nested results in items.', 'Input must be an array and stay within node and platform limits; nesting consumes recursion depth.'),
  LOOP: nodeDoc('Runs a nested graph while a condition is true, exposing index and last output.', 'Loop condition, maximum iterations, and nested graph.', 'Returns iterations and each result in items.', 'Fails when the limit is reached before exit; nesting and total execution steps are bounded.'),
  SWITCH: nodeDoc('Checks cases in order and selects the first matching named branch.', 'Cases containing branch and condition, plus a default branch.', 'Returns matched and branch, then continues from that named port.', 'At least one case is required and branch names should be unique; unmatched input uses only the default.'),
  MERGE: nodeDoc('Combines resolved values as an array or object.', 'Values and ARRAY/OBJECT mode.', 'ARRAY returns an array; OBJECT merges objects with later keys overwriting earlier keys.', 'OBJECT accepts only objects or object arrays and does not warn about overwritten keys.'),
  SUB_WORKFLOW: nodeDoc('Synchronously invokes a published workflow owned by the same user.', 'Published workflow code and inputs matching its input schema.', 'Returns the child workflow output and records the parent-child run relationship.', 'Cross-owner calls and recursion cycles are forbidden; depth, timeout, and publication state apply.'),
  WAIT: nodeDoc('Persists a wait state and resumes after the configured duration.', 'SECONDS or MILLISECONDS mode and its positive duration.', 'Resumes with the original context and produces no business payload.', 'Allowed only in a top-level graph; duration and resume leases are bounded.'),
  SET_VARIABLE: nodeDoc('Resolves output into a new structured value.', 'Any JSON value containing restricted context expressions.', 'Returns the resolved value while preserving its JSON type.', 'Does not mutate global variables or upstream output; unsafe keys and oversized payloads are rejected.'),
  TEMPLATE: nodeDoc('Replaces restricted variable references to produce text.', 'Template text and input, nodes, or loop context.', 'Returns an object containing text.', 'Does not execute scripts or arbitrary expressions; missing paths follow expression rules.'),
  JSON_PARSE: nodeDoc('Parses text as JSON or copies an already structured value.', 'JSON text or an existing JSON value.', 'Returns the parsed object, array, or scalar.', 'Invalid JSON fails the node and output remains payload-limited.'),
  JSON_VALIDATE: nodeDoc('Validates data with the supported JSON Schema subset.', 'Value, schema, and failOnError flag.', 'Returns valid, the original value, and errors.', 'Supports common types, required, properties, items, and maxLength; failOnError stops on violations.'),
  TRANSFORM: nodeDoc('Maps context expressions into a target JSON structure.', 'Target output structure containing restricted expressions.', 'Returns the resolved target structure.', 'Does not execute custom code; missing references and payload size follow platform rules.'),
  FILTER: nodeDoc('Creates item context for each array member and applies a condition.', 'Array collection and a condition referencing item/itemIndex.', 'Returns matching elements in original order.', 'Collection must resolve to an array and invalid conditions fail the node.'),
  SORT: nodeDoc('Stably sorts an array by an optional field path.', 'Array collection, path, and ASC/DESC direction.', 'Returns a sorted deep copy of the array.', 'Comparison is scalarized; nulls, mixed types, and missing paths may produce unexpected business order.'),
  AGGREGATE: nodeDoc('Runs COUNT, SUM, AVG, MIN, or MAX over an array.', 'Array collection, operation, and optional numeric path.', 'Returns an object containing value.', 'Operations other than COUNT require a non-empty numeric set; invalid or empty input fails.'),
  CSV: nodeDoc('Converts between header-based CSV text and object arrays.', 'CSV text for PARSE or an object array for STRINGIFY.', 'PARSE returns objects; STRINGIFY returns text.', 'Custom dialects are unsupported; malformed CSV and non-object rows fail and payload limits apply.'),
  QUESTION_CLASSIFIER: nodeDoc('Asks a model to select one finite, unique category name.', 'Question text, at least two categories, and model configuration.', 'Returns category and selects the matching category branch.', 'The model must return an allowed name; malformed or unknown classifications fail.'),
  PARAMETER_EXTRACTOR: nodeDoc('Asks a model to extract parameters according to JSON Schema.', 'Input text, object schema, and model configuration.', 'Returns the generated JSON object.', 'Output must be an object containing required fields; model output is not guaranteed to be factually correct.'),
  STRUCTURED_OUTPUT: nodeDoc('Parses text or JSON and enforces schema validation.', 'Value and the supported JSON Schema subset.', 'Returns the validated structured value and validation data.', 'Invalid JSON or schema mismatch fails; only the platform schema subset is available.'),
  DOCUMENT_EXTRACTOR: nodeDoc('Extracts body text and metadata from text or a Base64 document.', 'TEXT/BASE64 content, optional filename, and character limit.', 'Returns text and metadata.', 'Empty, invalid, unsupported, oversized, or over-limit documents fail; embedded scripts are not run.'),
  WEBHOOK_TRIGGER: nodeDoc('Starts a workflow from an authenticated and deduplicated webhook event.', 'Payload and trigger metadata from a managed webhook connection.', 'Returns trigger input unchanged.', 'Entry-only; request size, signature, rate, deduplication, and connection ownership are enforced.'),
  SCHEDULE_TRIGGER: nodeDoc('Creates workflow runs from a Cron expression and time zone.', 'Cron, IANA time zone, and schedule metadata.', 'Returns schedule input for downstream nodes.', 'Entry-only; invalid Cron/time zones are rejected and delivery depends on scheduler availability.'),
  EMAIL_SEND: nodeDoc('Sends a subject and body through a managed mail route.', 'Mail route, single-line subject, body, and expressions.', 'Returns sent and routeCode.', 'The route must be sendable, subject newlines are rejected, and sent mail cannot be rolled back.'),
  IM_NOTIFY: nodeDoc('Sends a notification through a managed webhook connection.', 'Connection, body, content type, and timeout.', 'Returns httpStatus, durationMs, and response body.', 'The managed target and egress policy are enforced; remote side effects cannot be rolled back.'),
  SQL_QUERY: nodeDoc('Executes a parameterized statement on managed MySQL or PostgreSQL.', 'Connection, one SQL statement, parameters, timeout, and row limit.', 'Queries return count/rows; writes return updated.', 'Semicolons/comments are forbidden, writes require connection permission, and at most 10,000 rows return.'),
  REDIS_COMMAND: nodeDoc('Runs an allowlisted Redis command with the managed key prefix.', 'Connection, supported command, and argument array.', 'Returns value with a command-dependent type.', 'Writes require connection permission; commands/arguments are allowlisted and remote writes cannot roll back.'),
  S3_OBJECT: nodeDoc('Runs GET, PUT, LIST, or DELETE within a managed bucket and key prefix.', 'Connection, operation, bucket, key/prefix, and optional upload content.', 'Returns download, list, upload, or delete data for the operation.', 'Scope cannot escape the connection; delete requires permission, transfers are size-limited, and effects persist.'),
  KAFKA_PUBLISH: nodeDoc('Publishes to an allowed Kafka topic and waits for broker acknowledgement.', 'Connection, topic, optional key, value, and timeout.', 'Returns topic, partition, and offset.', 'Topic must match the connection prefix and acknowledged messages cannot be rolled back.'),
  KAFKA_TRIGGER: nodeDoc('Consumes a managed Kafka message and starts the workflow.', 'Connection, topic, consumer group, and message payload.', 'Returns trigger input unchanged.', 'Entry-only; topic scope, deduplication, acknowledgement, and ownership are platform-controlled.'),
  RABBITMQ_PUBLISH: nodeDoc('Publishes to a managed RabbitMQ exchange/default exchange and waits for confirmation.', 'Connection, destination mode, exchange/routing key, value, and timeout.', 'Returns published and the actual exchange.', 'Destination scope is enforced and confirmed messages cannot be rolled back.'),
  RABBITMQ_TRIGGER: nodeDoc('Consumes a managed RabbitMQ queue message and starts the workflow.', 'Connection, queue, optional exchange/routing key, and message payload.', 'Returns trigger input unchanged.', 'Entry-only; queue scope, deduplication, acknowledgement, and ownership are controlled.'),
  TAVILY_TOOL: nodeDoc('Calls official Tavily Search or Extract through an encrypted managed connection.', 'Connection, operation, and its query, URL, depth, or format settings.', 'Returns httpStatus, durationMs, body, and json when parsable.', 'Search is capped at 20 results; only fixed official HTTPS endpoints are used and non-2xx/oversized responses fail.')
}

